const CACHE='mathlab-texas-v18';
const FILES=['./','index.html','portal.css','portal.js','portal-data.js','labs.html','style.css','ipad.css','app.js','pwa.js','content.js','english.js','ui-en.js','guide-en.html','guide.html','steam.html','steam.css','steam.js','teks-k5.js','pilot.html','pilot.css','pilot-data.js','pilot.js','fraction.html','fraction-data.js','fraction.js','cloud-sync.js','sync-model.js','icon.svg','apple-touch-icon.png','icon-192.png','icon-512.png','icon-maskable-512.png','manifest.webmanifest'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(FILES)).then(()=>self.skipWaiting()))});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key.startsWith('mathlab-texas-')&&key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim()))});
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;event.respondWith(fetch(event.request).then(async response=>{if(response.ok&&!response.redirected){const cache=await caches.open(CACHE);await cache.put(event.request,response.clone());return response}const cached=await caches.match(event.request);return cached||response}).catch(async()=>{const url=new URL(event.request.url);const file=url.pathname.split('/').pop()||'index.html';const exact=await caches.match(event.request);const withoutQuery=await caches.match(file);return exact||withoutQuery||(event.request.mode==='navigate'?caches.match('index.html'):Response.error())}))});
